<template>
  <div class="page-shell"><div class="page-heading"><div><h1>巡查任务</h1><p>民警扫描智慧门牌到场签到，保存时间、经纬度与现场记录。</p></div><el-button v-if="auth.role==='ADMIN'" type="primary" @click="openTask"><el-icon><Plus/></el-icon>新建巡查任务</el-button></div>
    <section class="panel"><div class="toolbar"><el-input v-model="query.keyword" clearable placeholder="任务、房屋或民警" style="width:250px"/><el-select v-model="query.status" clearable placeholder="任务状态" style="width:145px"><el-option v-for="(v,k) in statuses" :key="k" :label="v" :value="k"/></el-select><el-button @click="load"><el-icon><Search/></el-icon>查询</el-button><el-button @click="reset">重置</el-button></div><div class="table-wrap"><el-table :data="page.records" v-loading="loading"><el-table-column prop="title" label="巡查任务" min-width="180"><template #default="s"><b>{{s.row.title}}</b><small class="sub">{{priorityText[s.row.priority]}}优先级</small></template></el-table-column><el-table-column prop="houseName" label="巡查房屋" min-width="230"/><el-table-column prop="policeName" label="执行民警" width="110"/><el-table-column prop="plannedDate" label="计划日期" width="110"/><el-table-column label="任务状态" width="110"><template #default="s"><el-tag :type="statusType[s.row.status]">{{statuses[s.row.status]}}</el-tag></template></el-table-column><el-table-column prop="completedAt" label="完成时间" width="170"/><el-table-column label="操作" width="190" fixed="right"><template #default="s"><el-button v-if="s.row.status!=='COMPLETED'" link type="primary" @click="openComplete(s.row)">签到完成</el-button><el-button link @click="showDetail(s.row)">详情</el-button><el-popconfirm v-if="auth.role==='ADMIN'&&s.row.status!=='COMPLETED'" title="确认删除任务？" @confirm="remove(s.row.id)"><template #reference><el-button link type="danger">删除</el-button></template></el-popconfirm></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="query.pageNum" :total="page.total" layout="total,prev,pager,next" @current-change="load"/></div></div></section>
    <el-dialog v-model="taskDialog" title="新建巡查任务" width="600px"><el-form ref="taskFormRef" :model="taskForm" :rules="taskRules" label-width="90px"><el-form-item label="任务标题" prop="title"><el-input v-model="taskForm.title"/></el-form-item><el-form-item label="巡查房屋" prop="houseId"><el-select v-model="taskForm.houseId" filterable style="width:100%"><el-option v-for="h in houses" :key="h.id" :label="h.label" :value="h.id"/></el-select></el-form-item><el-form-item label="执行民警" prop="policeId"><el-select v-model="taskForm.policeId" style="width:100%"><el-option v-for="p in police" :key="p.id" :label="p.label" :value="p.id"/></el-select></el-form-item><el-row :gutter="14"><el-col :span="12"><el-form-item label="计划日期" prop="plannedDate"><el-date-picker v-model="taskForm.plannedDate" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="优先级"><el-select v-model="taskForm.priority" style="width:100%"><el-option label="低" value="LOW"/><el-option label="普通" value="NORMAL"/><el-option label="高" value="HIGH"/></el-select></el-form-item></el-col></el-row><el-form-item label="任务说明"><el-input v-model="taskForm.description" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="taskDialog=false">取消</el-button><el-button type="primary" @click="createTask">创建任务</el-button></template></el-dialog>
    <el-dialog v-model="completeDialog" title="巡查签到" width="620px"><div class="checkin-banner"><el-icon><LocationFilled/></el-icon><div><b>{{current.title}}</b><span>{{current.houseName}}</span></div><el-button size="small" @click="locate" :loading="locating">获取位置</el-button></div><el-alert :title="locationText" :type="completeForm.longitude?'success':'info'" :closable="false" show-icon/><el-form ref="completeFormRef" :model="completeForm" :rules="completeRules" label-width="90px" style="margin-top:20px"><el-form-item label="巡查内容" prop="content"><el-input v-model="completeForm.content" type="textarea" :rows="4" placeholder="填写人员核验、安全情况等巡查内容"/></el-form-item><el-form-item label="异常说明"><el-input v-model="completeForm.exceptionDescription" type="textarea" :rows="3"/></el-form-item><el-form-item label="现场图片"><el-upload action="/api/files/upload" :headers="uploadHeaders" list-type="picture-card" :limit="3" :on-success="imageUploaded"><el-icon><Plus/></el-icon></el-upload></el-form-item></el-form><template #footer><el-button @click="completeDialog=false">取消</el-button><el-button type="primary" @click="complete">提交巡查记录</el-button></template></el-dialog>
    <el-drawer v-model="detailDrawer" title="巡查任务详情" size="520px"><el-descriptions :column="1" border><el-descriptions-item label="任务">{{current.title}}</el-descriptions-item><el-descriptions-item label="房屋">{{current.houseName}}</el-descriptions-item><el-descriptions-item label="执行民警">{{current.policeName}}</el-descriptions-item><el-descriptions-item label="签到时间">{{current.checkinTime||'尚未签到'}}</el-descriptions-item><el-descriptions-item label="经纬度">{{current.longitude||'—'}}，{{current.latitude||'—'}}</el-descriptions-item><el-descriptions-item label="巡查内容">{{current.content||'—'}}</el-descriptions-item><el-descriptions-item label="异常说明">{{current.exceptionDescription||'无'}}</el-descriptions-item><el-descriptions-item label="现场照片"><div v-if="imageList(current.imageUrls).length" class="image-grid"><el-image v-for="image in imageList(current.imageUrls)" :key="image" :src="image" :preview-src-list="imageList(current.imageUrls)" fit="cover" preview-teleported/></div><span v-else>未上传现场照片</span></el-descriptions-item></el-descriptions></el-drawer>
  </div>
</template>
<script setup>
import{computed,onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import dayjs from'dayjs';import http from'../api/http';import{useAuthStore}from'../stores/auth';const auth=useAuthStore(),statuses={PENDING:'待执行',IN_PROGRESS:'执行中',COMPLETED:'已完成',OVERDUE:'已逾期'},statusType={PENDING:'warning',IN_PROGRESS:'primary',COMPLETED:'success',OVERDUE:'danger'},priorityText={LOW:'低',NORMAL:'普通',HIGH:'高'},query=reactive({pageNum:1,pageSize:10,keyword:'',status:''}),page=reactive({records:[],total:0}),loading=ref(false),houses=ref([]),police=ref([]),taskDialog=ref(false),completeDialog=ref(false),detailDrawer=ref(false),current=ref({}),taskFormRef=ref(),completeFormRef=ref(),locating=ref(false),taskForm=reactive({title:'出租房屋例行巡查',houseId:null,policeId:null,description:'核对房屋和居住人员信息，排查安全隐患。',plannedDate:dayjs().add(1,'day').format('YYYY-MM-DD'),priority:'NORMAL'}),completeForm=reactive({longitude:null,latitude:null,content:'',exceptionDescription:'',imageUrls:''}),taskRules={title:[{required:true,message:'请输入任务标题'}],houseId:[{required:true,message:'请选择房屋'}],policeId:[{required:true,message:'请选择民警'}],plannedDate:[{required:true,message:'请选择日期'}]},completeRules={content:[{required:true,message:'请填写巡查内容'}]},uploadHeaders=computed(()=>({Authorization:`Bearer ${auth.token}`})),locationText=computed(()=>completeForm.longitude?`已获取位置：${completeForm.longitude}，${completeForm.latitude}`:'经纬度仅作为签到数据保存，定位失败仍可提交。');onMounted(async()=>{if(auth.role==='ADMIN'){houses.value=await http.get('/houses/options');police.value=await http.get('/users/options',{params:{role:'POLICE'}})}load()});async function load(){loading.value=true;try{Object.assign(page,await http.get('/patrols/tasks',{params:query}))}finally{loading.value=false}}function reset(){query.keyword='';query.status='';query.pageNum=1;load()}function openTask(){taskDialog.value=true}async function createTask(){await taskFormRef.value.validate();await http.post('/patrols/tasks',taskForm);ElMessage.success('巡查任务已创建并通知民警');taskDialog.value=false;load()}function openComplete(row){current.value=row;Object.assign(completeForm,{longitude:null,latitude:null,content:'',exceptionDescription:'',imageUrls:''});completeDialog.value=true;locate()}function locate(){if(!navigator.geolocation){ElMessage.info('当前浏览器不支持定位');return}locating.value=true;navigator.geolocation.getCurrentPosition(p=>{completeForm.longitude=Number(p.coords.longitude.toFixed(8));completeForm.latitude=Number(p.coords.latitude.toFixed(8));locating.value=false},()=>{locating.value=false;ElMessage.info('未获取定位，可继续填写并提交')},{timeout:6000})}function imageUploaded(res){if(res.code===0)completeForm.imageUrls=[completeForm.imageUrls,res.data.url].filter(Boolean).join(',')}async function complete(){await completeFormRef.value.validate();await http.post(`/patrols/tasks/${current.value.id}/complete`,completeForm);ElMessage.success('巡查记录已提交');completeDialog.value=false;load()}function imageList(value){return String(value||'').split(',').map(item=>item.trim()).filter(Boolean)}function showDetail(row){current.value=row;detailDrawer.value=true}async function remove(id){await http.delete(`/patrols/tasks/${id}`);ElMessage.success('任务已删除');load()}
</script>
<style scoped>.sub{display:block;color:#91a3ac;font-size:10px;margin-top:5px}.checkin-banner{display:flex;align-items:center;gap:12px;background:#f0f7f6;border:1px solid #dbeae7;padding:14px;border-radius:10px;margin-bottom:12px}.checkin-banner>.el-icon{font-size:25px;color:#0e8a7a}.checkin-banner div{flex:1}.checkin-banner b,.checkin-banner span{display:block}.checkin-banner span{font-size:11px;color:#77909c;margin-top:5px}.image-grid{display:flex;flex-wrap:wrap;gap:10px}.image-grid :deep(.el-image){width:92px;height:72px;border-radius:8px;cursor:zoom-in}.image-grid>span{color:#8a9ba4;font-size:12px}</style>
